var t=`0992-gua-bao`;var i=`world-0992`;var n=`TW`;var s=`east-asia`;var r=8;var o=236;var l={en:`Gua Bao`,ua:`Гуа бао`};var u={en:`Gua Bao is a Taiwan dish made with pork belly, light soy sauce, all-purpose flour, instant yeast. This home-scale recipe assigns measured ingredients to the steps where they are used. Fresh homemade steamed buns replace prepared gua bao buns.`,ua:`Гуа бао, страва кухні країни Тайвань. Основні складники: свиняча грудинка, світлий соєвий соус, пшеничне борошно універсальне, інстантні дріжджі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Свіжі домашні парові булочки замінюють готові булочки для гуа бао.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`pork-belly`,780,`g`],[`light-soy-sauce`,60,`ml`],[`shaoxing-wine`,40,`ml`],[`chinese-five-spice`,6,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 80 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 80 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:80,i:[[`water`,610,`ml`],[`white-granulated-sugar`,45,`g`]]},{en:`Knead and proof the bun dough until doubled, divide into ovals and fold each around a small parchment square before steaming.`,ua:`Вимісіть і вистійте тісто для булочок до подвоєння, поділіть на овали й зігніть кожен навколо шматочка пергаменту перед пропарюванням.`,t:[`bulk-fermentation`],m:75,i:[[`all-purpose-flour`,420,`g`],[`water`,230,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,25,`g`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Put the prepared parcels in a steamer over gently boiling water, cover, and steam for about 16 minutes until the filling is completely cooked.`,ua:`Покладіть підготовлені вироби на решітку пароварки над водою, що ледь кипить, накрийте й готуйте на парі приблизно 16 хвилин до повної готовності начинки.`,t:[`steaming`],m:16,i:[]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`pickled-cucumber`,165,`g`],[`cilantro`,35,`g`],[`peanut`,85,`g`]]}];var g={slug:t,id:i,country:`TW`,region:s,servings:8,minutes:236,title:l,text:u,steps:d};export{n as country,g as default,i as id,o as minutes,s as region,r as servings,t as slug,d as steps,u as text,l as title};